import React from 'react';

const Contact = () => {
  return (
    <div style={{ padding: '20px', marginTop: '20px' }}>
      <h1>Contact Page</h1>
      <p>You can reach us at: contact@example.com</p>
    </div>
  );
};

export default Contact;
